contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // winnersArrayLen: number of winners to pass (must match winnersPerPeriod)
    // winners: an array of token ids to be selected as winners
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0);

        // read current round and selection status
        uint256 beforeRound = c.roundId();
        bool beforeComplete = c.isSelectionComplete(beforeRound);

        // read totalPoints and fighterPoints sums for provided winners
        uint256 beforeTotalPoints = c.totalPoints();
        uint256 sumFighterPoints = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            sumFighterPoints += c.fighterPoints(winners[i]);
        }

        // attempt to pick winners; may revert if not admin or incorrect length
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-state values
        uint256 afterRound = c.roundId();
        bool afterComplete = c.isSelectionComplete(beforeRound);
        uint256 afterTotalPoints = c.totalPoints();
        uint256 sumFighterPointsAfter = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            sumFighterPointsAfter += c.fighterPoints(winners[i]);
        }

        // General property:
        // If pickWinner did not revert, then
        //  - before the call the selection for that round must have been incomplete,
        //  - after the call isSelectionComplete[beforeRound] is true,
        //  - roundId increased by 1,
        //  - each selected winner's fighterPoints are reset to 0 (so their sum decreased by sumFighterPoints),
        //  - and totalPoints decreased by exactly the sum of fighterPoints for those winners.
        assert(
            reverted || (
                !beforeComplete &&
                afterComplete &&
                afterRound == beforeRound + 1 &&
                sumFighterPointsAfter == 0 &&
                afterTotalPoints + sumFighterPoints == beforeTotalPoints
            )
        );
    }

    receive() external payable {}
}

