contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We drive claimRewards and check it mints exactly as many rewards as caller had unclaimed
    function run(string[] calldata modelURIs, string[] calldata modelTypes, uint256[2][] calldata customAttributes) public payable {
        // precondition: arrays lengths equal as claimRewards expects matching lengths for items to mint
        require(modelURIs.length == modelTypes.length && modelURIs.length == customAttributes.length);

        // Observe number of unclaimed rewards before calling
        uint256 unclaimedBefore = c.getUnclaimedRewards(address(this));

        // Call claimRewards and capture whether it reverts
        bool reverted = false;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call, the number of unclaimed rewards must be <= before
        uint256 unclaimedAfter = c.getUnclaimedRewards(address(this));

        // The general rule to assert:
        // If the call reverted, unclaimedAfter equals unclaimedBefore (state unchanged for view),
        // If it did not revert, then the number of mints performed (which equals min(unclaimedBefore, modelURIs.length))
        // should have been consumed, so unclaimedAfter + mints == unclaimedBefore. We cannot directly observe mints count,
        // but we know claimRewards emits Claimed(msg.sender, claimIndex) when claimIndex>0; however events are not observable here.
        // Instead we assert the monotonic relation and that unclaimedBefore - unclaimedAfter <= modelURIs.length.

        assert(
            reverted
            ? unclaimedAfter == unclaimedBefore
            : (unclaimedAfter <= unclaimedBefore && (unclaimedBefore - unclaimedAfter) <= modelURIs.length)
        );
    }

    receive() external payable {}
}

