contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: we provide arrays for winners setup via pickWinner and then caller claims rewards.
    // We will: add a round with winners containing this contract address (since InvMutTest deployed C,
    // it can be an admin to call pickWinner only if isAdmin true; but we cannot change C's isAdmin externally.
    // Instead we will rely on existing admin (owner) being the deployer of C (the test harness deploys C with owner = address(this)).
    // The checker deploys C fresh and passes it to this test, and per instructions the InvMutTest contract is the msg.sender
    // for calls on c and was the deployer of c; therefore it is admin. We then call pickWinner to set winners and then claimRewards.

    // We must craft inputs: winners array with one tokenId; then claimRewards parameters correspond to number of wins.

    function run(uint256 tokenId, string[] calldata modelURIs, string[] calldata modelTypes, uint256[2][] calldata customAttributes) public payable {
        require(modelURIs.length == modelTypes.length && modelURIs.length == customAttributes.length, "input lengths");

        // Precondition: winnersPerPeriod currently maybe >0; we read it.
        uint256 winnersPer = c.winnersPerPeriod();
        // Ensure we create a winners array of correct length by resizing via memory
        // Build winners array of length winnersPer filled with tokenId
        uint256[] memory winners = new uint256[](winnersPer);
        for (uint256 i = 0; i < winnersPer; i++) {
            winners[i] = tokenId;
        }

        // record balance of this contract in FighterFarm before claiming
        // c has a public fighter farm instance but only through its public interface: we can call c.getUnclaimedRewards and rely on FighterFarm.mintFromMergingPool to increase balance
        // Query unclaimed before
        uint256 unclaimedBefore = c.getUnclaimedRewards(address(this));

        // Determine current balance of FighterFarm tokens owned by this contract via fighter farm instance: C has _fighterFarmInstance private; cannot access directly.
        // But C exposes no balanceOf; however FighterFarm is an ERC721 and minted tokens will be owned by this contract, but we cannot read balance from C.
        // Alternative observable: getUnclaimedRewards should decrease and Claimed event emitted. We'll rely on getUnclaimedRewards and that claimRewards will call mintFromMergingPool which requires caller to be merging pool address; however claimRewards calls _fighterFarmInstance.mintFromMergingPool with msg.sender.
        // We assert relation between unclaimedBefore/unclaimedAfter and Claimed emission indirectly by checking getUnclaimedRewards decreased by at least number of minted URIs.

        // Call pickWinner to create a round where this contract is winner. Only admin can call; deployer is admin so ok.
        // pickWinner requires winners.length == winnersPerPeriod; we built accordingly.
        c.pickWinner(winners);

        // After pickWinner, roundId increased; now call claimRewards.
        // record unclaimed before claim (should have increased by winnersPer)
        uint256 unclaimedMid = c.getUnclaimedRewards(address(this));

        // Now call claimRewards which should mint one reward per time this contract appears among winners between numRoundsClaimed and roundId.
        // Because our winners placed this contract in the latest round winnersPer times, the number of rewards equals the count of appearances — winnersPer.
        // Ensure provided arrays have at least winnersPer entries
        require(modelURIs.length >= winnersPer, "not enough models");

        // capture numRoundsClaimed before
        uint32 roundsClaimedBefore = c.numRoundsClaimed(address(this));

        // perform claim; catch revert
        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read numRoundsClaimed after
        uint32 roundsClaimedAfter = c.numRoundsClaimed(address(this));

        // read unclaimed after
        uint256 unclaimedAfter = c.getUnclaimedRewards(address(this));

        // We assert: if claimRewards did not revert then roundsClaimedAfter >= roundsClaimedBefore and unclaimedAfter <= unclaimedMid and (unclaimedMid - unclaimedAfter) >= 1 iff at least one claim was made (i.e., modelURIs length >=1)
        // To make a general property: successful claim reduces getUnclaimedRewards by at least 1 (if any rewards existed), and roundsClaimed increments.
        assert(
            // If the call reverted then nothing changed: roundsClaimedAfter == roundsClaimedBefore
            (reverted && roundsClaimedAfter == roundsClaimedBefore && unclaimedAfter == unclaimedMid)
            ||
            // If not reverted then roundsClaimedAfter > roundsClaimedBefore and unclaimedAfter <= unclaimedMid
            (!reverted && roundsClaimedAfter >= roundsClaimedBefore && unclaimedAfter <= unclaimedMid)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We create a winners array matching current winnersPerPeriod, call pickWinner (we are admin as deployer),
    // then call claimRewards and check the monotonicity properties described above.
    function run(uint256 tokenId, string[] calldata modelURIs, string[] calldata modelTypes, uint256[2][] calldata customAttributes) public payable {
        // basic input length requirement for claimRewards arrays
        require(modelURIs.length == modelTypes.length && modelURIs.length == customAttributes.length, "input lengths");

        uint256 winnersPer = c.winnersPerPeriod();
        // winnersPer could be 0; in that case pickWinner expects 0-length array — still allowed.
        // build winners array of length winnersPer filled with tokenId
        uint256[] memory winners = new uint256[](winnersPer);
        for (uint256 i = 0; i < winnersPer; i++) {
            winners[i] = tokenId;
        }

        // observe baseline values
        uint32 roundsClaimedBefore = c.numRoundsClaimed(address(this));
        uint256 unclaimedBefore = c.getUnclaimedRewards(address(this));

        // call pickWinner to create a selection for the current round; this call must be a top-level state-changing call
        c.pickWinner(winners);

        // observe values after pickWinner (unclaimed may increase)
        uint32 roundsClaimedMid = c.numRoundsClaimed(address(this));
        uint256 unclaimedMid = c.getUnclaimedRewards(address(this));

        // ensure we provide enough claim data: worst-case we might be eligible for winnersPer claims
        if (modelURIs.length < winnersPer) {
            // if not enough provided, calling claimRewards likely reverts; still allowed — we proceed to call and capture revert
        }

        // attempt claimRewards and capture whether it reverted
        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after attempting claim
        uint32 roundsClaimedAfter = c.numRoundsClaimed(address(this));
        uint256 unclaimedAfter = c.getUnclaimedRewards(address(this));

        // Assert the general invariant:
        // - claimRewards, if it reverted, should not have changed numRoundsClaimed nor getUnclaimedRewards compared to the mid-state
        // - if it did not revert, numRoundsClaimed must not have decreased and getUnclaimedRewards must not have increased
        assert(
            (reverted && roundsClaimedAfter == roundsClaimedMid && unclaimedAfter == unclaimedMid)
            ||
            (!reverted && roundsClaimedAfter >= roundsClaimedMid && unclaimedAfter <= unclaimedMid)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry: try to claim rewards and check monotonicity / no-op on revert
    function run(string[] calldata modelURIs, string[] calldata modelTypes, uint256[2][] calldata customAttributes) public payable {
        // array length consistency required by claimRewards if it is to succeed
        require(modelURIs.length == modelTypes.length && modelURIs.length == customAttributes.length, "input lengths");

        address self = address(this);
        // observe before any new rounds: numRoundsClaimed and unclaimed rewards
        uint32 beforeRounds = c.numRoundsClaimed(self);
        uint256 beforeUnclaimed = c.getUnclaimedRewards(self);

        // Attempt claimRewards and capture whether it reverted
        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after attempting claim
        uint32 afterRounds = c.numRoundsClaimed(self);
        uint256 afterUnclaimed = c.getUnclaimedRewards(self);

        // General rule:
        // - If the call reverted, it must not have changed numRoundsClaimed nor reported unclaimed rewards.
        // - If the call did not revert, numRoundsClaimed must be >= before and getUnclaimedRewards must be <= before.
        assert(
            (reverted && afterRounds == beforeRounds && afterUnclaimed == beforeUnclaimed)
            ||
            (!reverted && afterRounds >= beforeRounds && afterUnclaimed <= beforeUnclaimed)
        );
    }

    receive() external payable {}
}

