    // unclaimed rewards exist for this contract address, then call claimRewards and check that
    // the number of minted fighters equals that unclaimed count. We also observe whether the
    // Claimed event would have been emitted indirectly by checking getUnclaimedRewards becomes zero
    // for the rounds considered. Because we can only observe via public surface, we use
    // getUnclaimedRewards before and after, and require that decrease equals number of mints.

    function run(string[] calldata modelURIs, string[] calldata modelTypes, uint256[2][] calldata customAttributes) public payable {
        // preconditions: arrays lengths must match for claimRewards input (the contract will revert otherwise)
        require(modelURIs.length == modelTypes.length && modelURIs.length == customAttributes.length, "input length mismatch");

        // Observe unclaimed rewards for this contract (msg.sender for c calls will be this test contract)
        uint256 beforeUnclaimed = c.getUnclaimedRewards(address(this));

        // Attempt to call claimRewards and catch revert
        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe unclaimed rewards after the call
        uint256 afterUnclaimed = c.getUnclaimedRewards(address(this));

        // The general rule to assert:
        // If the call reverted, the number of unclaimed rewards must be unchanged. If it did not revert,
        // then the number of unclaimed rewards must have decreased by at most the number of provided reward items
        // and not increased, and in particular beforeUnclaimed - afterUnclaimed <= modelURIs.length and afterUnclaimed <= beforeUnclaimed.
        // Also if some rewards were claimed (i.e., before>after) then the contract must have consumed at least one provided reward slot,
        // so (beforeUnclaimed > afterUnclaimed) implies modelURIs.length >= 1.

        assert(
            (reverted && afterUnclaimed == beforeUnclaimed) ||
            (!reverted && afterUnclaimed <= beforeUnclaimed && (beforeUnclaimed - afterUnclaimed) <= modelURIs.length && (beforeUnclaimed > afterUnclaimed ? modelURIs.length >= 1 : true))
        );
    }

    receive() external payable {}
}

