contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call with arbitrary inputs
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0);
        // read state before
        uint256 oldRoundId = c.roundId();
        bool oldIsComplete = c.isSelectionComplete(oldRoundId);

        // capture owner addresses and points for winners before calling pickWinner
        uint256 winnersLength = winners.length;
        address[] memory ownersBefore = new address[](winnersLength);
        uint256[] memory pointsBefore = new uint256[](winnersLength);
        for (uint256 i = 0; i < winnersLength; i++) {
            // ownerOf may revert if token doesn't exist; that's acceptable for the test input
            // so we guard by try/catch and set owner to address(0) on revert
            try c._fighterFarmInstance().ownerOf(winners[i]) returns (address o) {
                ownersBefore[i] = o;
            } catch {
                ownersBefore[i] = address(0);
            }
            // read points (public mapping getter)
            pointsBefore[i] = c.fighterPoints(winners[i]);
        }

        // attempt pickWinner and record whether it reverted
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read state after
        uint256 newRoundId = c.roundId();
        bool newIsCompleteOldRound = c.isSelectionComplete(oldRoundId);
        bool newIsCompleteNewRound = c.isSelectionComplete(newRoundId - 1);

        // If call reverted, nothing is required beyond that; but if it succeeded, then:
        // - if selection wasn't already complete for oldRoundId, roundId should increase by 1
        // - fighterPoints for each provided winner should be reset to 0
        // - winnerAddresses[oldRoundId] should equal the ownersBefore (for entries where owner was nonzero)

        // fetch stored winnerAddresses for the relevant round (if call succeeded and progressed)
        address[] memory recorded;
        if (!reverted && !oldIsComplete) {
            recorded = c.winnerAddresses(oldRoundId);
        } else {
            recorded = new address[](0);
        }

        // Build the assertion expressing the general rule
        // If the call succeeded and selection wasn't complete, then:
        //   newRoundId == oldRoundId + 1
        //   for each winner i: c.fighterPoints(winner[i]) == 0
        //   recorded.length == winners.length and for entries where ownersBefore[i] != address(0) recorded[i] == ownersBefore[i]
        // Otherwise (if reverted or already complete) there is no requirement about these changes.

        bool ok;
        if (!reverted && !oldIsComplete) {
            bool roundAdvanced = (newRoundId == oldRoundId + 1);
            bool pointsCleared = true;
            for (uint256 i = 0; i < winnersLength; i++) {
                if (c.fighterPoints(winners[i]) != 0) { pointsCleared = false; break; }
            }
            bool winnersRecorded = (recorded.length == winnersLength);
            if (winnersRecorded) {
                for (uint256 i = 0; i < winnersLength; i++) {
                    if (ownersBefore[i] != address(0)) {
                        if (recorded[i] != ownersBefore[i]) { winnersRecorded = false; break; }
                    }
                }
            }
            ok = roundAdvanced && pointsCleared && winnersRecorded;
        } else {
            // If reverted or already complete, we only require that either it reverted or selection was already complete.
            ok = reverted || oldIsComplete;
        }

        assert(ok);
    }

    // helper to access nested public instance: we rely only on public getters
    receive() external payable {}
}

