        // assert that winnerAddresses stored after a successful pick correspond to owner addresses retrievable via
        // calling c.winnerAddresses for that round (i.e., consistency between recorded winners and what was stored).

        for (uint256 i = 0; i < winnersLength; i++) {
            pointsBefore[i] = c.fighterPoints(winners[i]);
            ownersBefore[i] = address(0); // placeholder since ownerOf of FighterFarm is not directly visible from C
        }

        // attempt pickWinner and record whether it reverted
        bool reverted;
        try c.pickWinner(winners) {
