        uint256 newRoundId = c.roundId();

        // If call succeeded and selection wasn't already complete, then roundId should increase by 1,
        // fighterPoints for each provided winner should be reset to 0, and winnerAddresses[oldRoundId] should have length == winners.length.
        // Otherwise (if reverted or already complete) either it reverted or selection was already complete.

        // fetch recorded winners for the relevant round when appropriate
        address[] memory recorded;
        if (!reverted && !oldIsComplete) {
            recorded = c.winnerAddresses(oldRoundId);
        } else {
            recorded = new address[](0);
        }

        bool ok;
        if (!reverted && !oldIsComplete) {
            // round advanced
            bool roundAdvanced = (newRoundId == oldRoundId + 1);
            // points cleared
            bool pointsCleared = true;
            for (uint256 i = 0; i < winnersLength; i++) {
                if (c.fighterPoints(winners[i]) != 0) { pointsCleared = false; break; }
            }
            // winners recorded length equals provided winners length
            bool winnersRecordedLength = (recorded.length == winnersLength);

            ok = roundAdvanced && pointsCleared && winnersRecordedLength;
        } else {
            // If reverted or already complete, require that at least one of those is true
            ok = reverted || oldIsComplete;
        }

        assert(ok);
    }

    receive() external payable {}
}

