            for (uint256 i = 0; i < n; i++) {
                if (c.fighterPoints(winners[i]) != 0) { pointsCleared = false; break; }
            }
            // winnerAddresses for the previous round (oldRoundId) should have length winnersPerPeriod
            address[] memory recorded = c.winnerAddresses(oldRoundId);
            bool winnersRecordedLength = (recorded.length == wp);
            // isSelectionComplete for oldRoundId must be true
            bool markedComplete = c.isSelectionComplete(oldRoundId);

            assert(roundAdvanced && pointsCleared && winnersRecordedLength && markedComplete);
        } else {
            // Otherwise, ensure that either the call reverted or nothing changed in roundId (no accidental advance)
            assert(reverted || newRoundId == oldRoundId);
        }
    }

    receive() external payable {}
}

