    constructor(C _c) {
        c = _c;
        // cast fighter farm instance from C's constructor arg is not possible here; will fetch via public getter not available,
        // so we will rely solely on C's public methods. We still declare ff to silence analyzer; won't use it.
    }

    // single public entry that performs the property test
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0);
        // Pre-read roundId and totalPoints
        uint256 beforeRound = c.roundId();
        uint256 beforeTotalPoints = c.totalPoints();

        // For safety require that msg.sender (this contract) isAdmin so pickWinner can be called.
        // We cannot set isAdmin on c because only owner can; but the deployed c sets the deployer as admin —
        // however our InvMutTest is not that admin. To make the test general, we call pickWinner and capture revert.
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call readings
        uint256 afterRound = c.roundId();
        uint256 afterTotalPoints = c.totalPoints();

        // If pickWinner reverted then nothing should have changed: roundId and totalPoints equal before.
        // If it did not revert then roundId must have increased by exactly 1, isSelectionComplete for previous round must be true,
        // and totalPoints must have decreased by sum of fighterPoints of winners (which we can observe partially by reading fighterPoints per id before/after).
        // We therefore read fighterPoints for each winner both before and after; but we can only call public getter fighterPoints(tokenId)
        // which exists on C, so do that.

        uint256 sumBefore = 0;
        uint256 sumAfter = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            uint256 id = winners[i];
            uint256 pBefore = c.fighterPoints(id);
            sumBefore += pBefore;
            uint256 pAfter = c.fighterPoints(id);
            sumAfter += pAfter;
        }

        // Assert general invariant combining both cases.
        // If reverted: beforeRound == afterRound and beforeTotalPoints == afterTotalPoints and sumBefore == sumAfter.
        // If not reverted: afterRound == beforeRound + 1, afterTotalPoints + sumBefore == beforeTotalPoints, and for each winner their fighterPoints became 0 (so sumAfter == 0).
        assert(
            (reverted && beforeRound == afterRound && beforeTotalPoints == afterTotalPoints && sumBefore == sumAfter)
            || (!reverted && afterRound == beforeRound + 1 && afterTotalPoints + sumBefore == beforeTotalPoints && sumAfter == 0)
        );
    }

    receive() external payable {}
}

