    function run(uint256[] calldata winnersPre, uint256 winnersPerPeriodInput) public payable {
        require(winnersPre.length == winnersPerPeriodInput, "mismatch length");
        // make caller an admin by calling adjustAdminAccess from contract deployer: constructor of C set deployer as owner (this test deployed C), so transfer of ownership not needed
        // The InvMutTest is the deployer of C per harness description, so it is owner and isAdmin by constructor. Use that to call addPoints then pickWinner.

        // first record totalPoints before
        uint256 totalBefore = c.totalPoints();

        // Add points for each provided token id via the allowed ranked battle address: need to simulate that caller is _rankedBattleAddress
        // But this contract is owner/admin; addPoints requires msg.sender == _rankedBattleAddress, so we cannot call addPoints successfully. Instead we rely on reading fighterPoints (public mapping) by using getFighterPoints
        // To create a meaningful precondition we instead assume some existing fighterPoints; we will read fighterPoints via getFighterPoints to compute sumBefore for first winnersPre.length indices.

        // Read points array for maxId = winnersPre.length (note getFighterPoints takes maxId and returns array length 1 in original — but still callable).
        uint256[] memory pts = c.getFighterPoints(winnersPre.length);
        // compute sum of points for indices in winnersPre
        uint256 sumPoints = 0;
        for (uint256 i = 0; i < winnersPre.length; i++) {
            uint256 id = winnersPre[i];
            // if id < pts.length then read, else treat as 0 (cannot read beyond returned array)
            if (id < pts.length) {
                sumPoints += pts[id];
            }
        }

        // set winnersPerPeriod to match input so pickWinner expects that many winners
        c.updateWinnersPerPeriod(winnersPerPeriodInput);

        // Try pickWinner and capture revert flag
        bool reverted;
        try c.pickWinner(winnersPre) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call, read totalPoints and isSelectionComplete for previous round (roundId before pick)
        uint256 roundBefore = c.roundId();
        // If pickWinner succeeded, isSelectionComplete for previous round should be true and totalPoints reduced by sum of fighterPoints for those winners (which should be zero afterwards).
        uint256 totalAfter = c.totalPoints();

        // If pickWinner reverted, we assert that nothing changed: totalPoints stays same and isSelectionComplete[roundBefore] is unchanged (i.e., false)
        bool selectionCompleteAfter = c.isSelectionComplete(roundBefore);

        // Final general assertion combining both cases
        assert(
            // If pickWinner reverted then total unchanged and selection not marked complete
            (reverted && totalAfter == totalBefore && selectionCompleteAfter == false)
            ||
            // If pickWinner succeeded then selection was marked complete for that round and total decreased by exactly sumPoints and fighterPoints for each winner are now zero
            (!reverted && selectionCompleteAfter == true && totalBefore >= totalAfter && totalBefore - totalAfter == sumPoints)
        );
    }

    receive() external payable {}
}

