            // Note: we can't read the exact revert reason, so check that either winners length mismatch (we ensured match) or isSelectionComplete already true
            // Therefore assert isSelectionComplete for current round prior to call (i.e., roundId()) or winners length mismatch (false here). So must be selection already complete
            uint256 curRound = c.roundId();
            bool already = c.isSelectionComplete(curRound);
            assert(already);
        }
    }

