contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function driving the property-based test
    function run(address caller, uint256[] calldata winners, bool callerIsAdminBefore) public payable {
        // We will use the contract's adjustAdminAccess to set admin status for `caller`.
        // The test contract is msg.sender when calling c, so make sure we only interact via c.

        // Set up: make `caller` either admin or not according to input by calling transferOwnership
        // and adjustAdminAccess through the owner account; but we can't change msg.sender identity.
        // Instead, use c.adjustAdminAccess from this contract only if this contract is owner —
        // The deployed C is fresh and its constructor set this test contract as owner? Not guaranteed.
        // So we instead observe current winnersPerPeriod and isSelectionComplete and roundId, and
        // attempt pickWinner via this test contract (which will act as caller). We can first ensure
        // winners.length equals or not equals winnersPerPeriod to test both behaviors.

        // Read pre-state
        uint256 preRoundId = c.roundId();
        bool preSelectionComplete = c.isSelectionComplete(preRoundId);
        uint256 preWinnersPerPeriod = c.winnersPerPeriod();

        // Decide expected behavior: if winners.length != winnersPerPeriod, pickWinner should revert for ANY caller
        bool expectRevertOnCall = (winners.length != preWinnersPerPeriod);

        // Make the call and capture revert
        bool reverted = false;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state values
        uint256 postRoundId = c.roundId();
        bool postSelectionCompletePre = c.isSelectionComplete(preRoundId);

        // General rule asserted:
        // - If winners.length != winnersPerPeriod then call must revert (reverted == true) and state unchanged (roundId same, isSelectionComplete unchanged)
        // - If winners.length == winnersPerPeriod and preSelectionComplete == false then call must NOT revert and roundId increments by 1 and isSelectionComplete[preRoundId] becomes true
        // Note: we cannot guarantee who is admin, so when winners.length==winnersPerPeriod the call may still revert if caller lacks admin; thus we only assert the implication for the mismatch case and the expected state-change when the call succeeded.

        if (expectRevertOnCall) {
            assert(reverted && postRoundId == preRoundId && postSelectionCompletePre == preSelectionComplete);
        } else {
            // when lengths match, if the call reverted then no state change; if it succeeded then roundId increased by 1 and selection marked complete
            if (reverted) {
                assert(postRoundId == preRoundId && postSelectionCompletePre == preSelectionComplete);
            } else {
                assert(postRoundId == preRoundId + 1 && postSelectionCompletePre == true);
            }
        }
    }

    receive() external payable {}
}
